import{_ as o,o as t,c as a,a2 as n}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"RFC 0085 — Vertical section navigation for overlay-shell plugins (NavRail)","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign/blob/main/docs/rfcs/0085-vertical-section-nav-overlay-shell.md"},"headers":[],"relativePath":"rfcs/0085-vertical-section-nav-overlay-shell.md","filePath":"rfcs/0085-vertical-section-nav-overlay-shell.md"}'),s={name:"rfcs/0085-vertical-section-nav-overlay-shell.md"};function i(c,e,d,l,r,u){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="rfc-0085-—-vertical-section-navigation-for-overlay-shell-plugins-navrail" tabindex="-1">RFC 0085 — Vertical section navigation for overlay-shell plugins (<code>NavRail</code>) <a class="header-anchor" href="#rfc-0085-—-vertical-section-navigation-for-overlay-shell-plugins-navrail" aria-label="Permalink to &quot;RFC 0085 — Vertical section navigation for overlay-shell plugins (\`NavRail\`)&quot;">​</a></h1><p><strong>Status:</strong> Partially implemented — Account&#39;s half fully shipped across tasks 14.5 and 14.6; Console&#39;s half superseded by workstream 0022&#39;s different design — see update below<br><strong>Date:</strong> August 2026<br><strong>Author:</strong> Claude Code + kasunben<br><strong>Scope:</strong> <code>packages/ui</code> (new component, <code>Dialog</code> sizing, Storybook), <code>plugins/console</code>, <code>plugins/account</code>, <code>docs/design-system.md</code>, <code>docs/plugin-development.md</code>. Related to <a href="./0076-ds-sizing-alignment-and-new-primitives.html">RFC 0076</a> (new-primitives precedent) and <a href="./0001-overlay-shell-variant.html">RFC 0001</a> (original overlay shell design).<br><strong>Incorporated into plan:</strong> Partially — Console&#39;s half (originally epic task 9.22 in the <a href="./../epics/design-system.html">Design System</a> epic) was rejected as scoped; see below. Account&#39;s half is scoped as <a href="./../epics/plugin-accounts.html">epic task 14.5</a> (desktop rail) and <a href="./../epics/plugin-accounts.html">epic task 14.6</a> (mobile drill-down nav) in the <a href="./../epics/plugin-accounts.html">Plugin — Accounts</a> epic.</p><blockquote><p><strong>Update:</strong> Written independently of, and in parallel with, <a href="./../workstreams/0022-console-shell-and-three-column-layout.html">workstream 0022</a>, which resolves the same underlying problem (Console&#39;s hand-rolled horizontal tab strip) for Console with a different, incompatible design: <code>shell: &quot;overlay&quot;</code> → <code>shell: &quot;default&quot;</code> (a real full page, not a resized dialog) plus <code>ThreeColumnLayout</code> and a new <code>NavList</code> component, including a mobile drill-down redesign this RFC had explicitly deferred as &quot;future work, not a follow-up task yet.&quot; The two designs surfaced as a genuine merge conflict (workstream 0022 had already shipped code before this RFC&#39;s existence was discovered); the developer chose to keep workstream 0022&#39;s direction for Console. <strong>This RFC&#39;s Console-specific proposal is superseded and will not be built as written</strong> — epic task 9.22 is marked Rejected accordingly. The <code>NavRail</code>-in-overlay pattern itself, and its application to Account (untouched by workstream 0022), are <strong>not</strong> rejected — they remain a live option, just no longer scoped as a single combined task with Console. A future task revisiting <code>NavRail</code> for Account alone would need to re-derive its own scope from this RFC rather than reuse rejected task 9.22.</p></blockquote><blockquote><p><strong>Update 2:</strong> Account&#39;s half re-scoped as <a href="./../epics/plugin-accounts.html">epic task 14.5</a>. Two changes from this RFC&#39;s original design, decided during that re-scoping: Account stays <code>shell: &quot;overlay&quot;</code> rather than following Console&#39;s <code>shell: &quot;default&quot;</code> conversion — Console&#39;s composition depends on a full-page height-unlock hook (<code>data-plugin-fullbleed</code>) that doesn&#39;t reach inside a <code>Dialog</code>. And no new <code>NavRail</code> component is built — <code>@sovereignfs/ui</code>&#39;s existing <code>NavList</code> (shipped for Console in workstream 0022 leg 1) has no such height dependency and drops into Account&#39;s <code>Dialog</code> directly, so this RFC&#39;s originally-proposed component work is no longer needed for Account either. The originally-planned <code>&quot;lg&quot; → &quot;md&quot;</code> resize itself did <strong>not</strong> ship as scoped, in three further rounds during implementation: task 14.5 first kept <code>overlaySize: &quot;lg&quot;</code> unchanged (<code>md</code>&#39;s content-driven height would have made the dialog resize between short and long sections, which <code>lg</code>&#39;s fixed box was specifically chosen to avoid), then, once <code>lg</code> itself read as oversized for a settings surface, switched to <code>@sovereignfs/ui</code>&#39;s existing <code>auto</code> size instead of <code>md</code> — content-driven on both axes, already used by runtime-direct <code>&lt;Dialog&gt;</code> callers, extended to the manifest <code>overlaySize</code> enum for the first time — and finally, once <code>auto</code>&#39;s own content-driven sizing turned out to visibly shrink to fit a near-empty intermediate page during Account&#39;s <code>/account</code> → <code>/account/profile</code> redirect before growing once real content landed, switched again to a new <code>DialogSize</code>, <code>fixed</code> — a true fixed box like <code>lg</code> (content never resizes it) but capped at <code>64rem × 44rem</code> instead of filling the viewport. See task 14.5&#39;s own Status note for the full three-round account.</p></blockquote><blockquote><p><strong>Update 3:</strong> This RFC&#39;s own Alternatives/Open-questions entries below (&quot;Ship the full mobile drill-down... Noted as explicit future work so it isn&#39;t lost&quot; / &quot;Full mobile drill-down list. Explicitly future work... not scheduled by this RFC&quot;) are picked up by <a href="./../epics/plugin-accounts.html">epic task 14.6</a>, scoped as a follow-up to 14.5 rather than folded into it. Account&#39;s mobile nav now matches the drill-down pattern Console itself shipped for its own mobile nav (task 13.17, workstream 0022): a full-screen index of tappable section rows, selecting one navigates into that section, which shows a <code>‹ Account</code> back-link instead of any persistent nav. See task 14.6&#39;s own Status note for the full account, including a real correctness risk found and resolved during planning (a redirect-vs-viewport race, same bug class as task 14.5&#39;s own rounds 3–4).</p></blockquote><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Console and Account currently render their section navigation (&quot;Users&quot;, &quot;Plugins&quot;, &quot;Settings&quot;... / &quot;Profile&quot;, &quot;Security&quot;, &quot;Data&quot;...) as a horizontal underline tab strip at the top of a full-screen (<code>overlaySize: &quot;lg&quot;</code>) dialog. This RFC proposes switching both to a <strong>vertical rail</strong> navigation pattern — similar to Claude&#39;s own desktop settings modal — backed by a new <code>packages/ui</code> primitive (<code>NavRail</code>), and shrinking the dialog both plugins render in from <code>lg</code> (full-screen) to a resized <code>md</code> (a fixed, landscape- oriented box) so the rail-plus-content layout doesn&#39;t sprawl across the whole viewport. Mobile keeps its current behavior unchanged in this pass.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>Console has 11 sections and Account has 7; a horizontal strip at this count already wraps or scrolls sideways, and a full-screen dialog for what is functionally a settings panel reads as heavier than the content warrants. A vertical rail scales better to a longer, flatter list of sections and matches a well-established pattern for exactly this kind of surface (OS preference panes, Claude&#39;s own settings modal, GitHub repo settings).</p><p>Separately, today&#39;s implementation is duplicated: Console and Account each hand-roll their own horizontal nav CSS rather than sharing a component, which is exactly the kind of drift <code>docs/design-system.md</code>&#39;s &quot;DS-first: plugins are consumers&quot; principle exists to prevent. This RFC&#39;s component work retires that duplication in the same pass as the visual change.</p><h2 id="current-state-what-this-builds-on" tabindex="-1">Current state (what this builds on) <a class="header-anchor" href="#current-state-what-this-builds-on" aria-label="Permalink to &quot;Current state (what this builds on)&quot;">​</a></h2><ul><li><strong>Overlay sizing already has three fixed-box sizes.</strong> <code>Dialog</code> (<code>packages/ui/src/components/Dialog/Dialog.tsx:59</code>) exposes <code>DialogSize = &#39;sm&#39; | &#39;md&#39; | &#39;lg&#39; | &#39;full&#39;</code>; the manifest schema (<code>packages/manifest/src/schema.ts:166</code>) already validates <code>overlaySize: z.enum([&#39;sm&#39;, &#39;md&#39;, &#39;lg&#39;])</code>. <code>md</code> is defined in <code>Dialog.module.css:108-113</code> as a fixed <code>36rem × 42rem</code> (576×672px, portrait) box, but <strong>no shipped plugin uses it</strong> — only the reference <code>example-plugins/example-overlay-medium</code>. Console and Account are both pinned to <code>overlaySize: &quot;lg&quot;</code> (<code>plugins/console/manifest.json</code>, <code>plugins/account/manifest.json</code>).</li><li><strong>Every size collapses to full-screen on mobile regardless of value</strong> (<code>Dialog.module.css:163-198</code>, <code>@media (max-width: 768px)</code>), so resizing <code>md</code> is a desktop-only concern.</li><li><strong>Three separate tab implementations already exist, none vertical:</strong><code>packages/ui</code>&#39;s <code>Tabs</code> (<code>components/Tabs/Tabs.tsx</code>, controlled <code>value</code>/<code>onChange</code>, ARIA <code>tablist</code>/<code>tab</code>, horizontal underline) and <code>NavTabs</code> (<code>components/NavTabs/NavTabs.tsx</code>, link-based <code>href</code>/<code>active</code>, horizontal underline) are both unused by Console/Account. Console (<code>runtime/app/(platform)/(plugins)/console/layout.tsx:16-44</code>, <code>console.module.css:20-51</code>, classes <code>.nav</code>/<code>.navLink</code>) and Account (<code>plugins/account/app/layout.tsx:8-32</code>, <code>account.module.css</code>, classes <code>.tabs</code>/<code>.tab</code>) each hand-roll a third, near-identical copy locally.</li><li><strong>Mobile tab-strip placement is a distinct, load-bearing mechanism.</strong><code>useOverlaySecondRow</code> (<code>Dialog.tsx:49-57</code>) lets a plugin layout hand its nav strip up to the enclosing <code>Dialog</code>&#39;s mobile <code>OverlayHeader</code>, which renders it as a second header row (<code>OverlayHeader.tsx:59</code>) — solving the &quot;double header&quot; problem where a plugin&#39;s own sticky strip would otherwise render a second time inside the scrolling content area. Both Console and Account layouts call this today; a vertical rail does not have a natural &quot;second row&quot; equivalent, so this RFC deliberately leaves mobile using the same mechanism unchanged (see Alternatives / Open questions).</li><li><strong><code>packages/ui</code> is a published, versioned public contract.</strong> Currently <code>0.47.0</code> (<code>packages/ui/package.json:3</code>). Per NFR-04, breaking changes need at minimum a minor bump and a migration note in <code>docs/upgrade.md</code>, regardless of whether any shipped plugin currently consumes the value being changed.</li><li><strong>No existing rail/sidebar DS primitive.</strong> Plugin-local sidebars exist (Shopper&#39;s <code>Sidebar.tsx</code>, Tasks&#39; <code>ListSidebar.tsx</code>, Tally&#39;s <code>GroupSidebar.tsx</code>) but are all data-list UIs specific to their plugin, not a generic vertical section-nav primitive.</li></ul><h2 id="proposed-design" tabindex="-1">Proposed design <a class="header-anchor" href="#proposed-design" aria-label="Permalink to &quot;Proposed design&quot;">​</a></h2><h3 id="a-new-component-—-navrail-packages-ui" tabindex="-1">A. New component — <code>NavRail</code> (<code>packages/ui</code>) <a class="header-anchor" href="#a-new-component-—-navrail-packages-ui" aria-label="Permalink to &quot;A. New component — \`NavRail\` (\`packages/ui\`)&quot;">​</a></h3><ul><li>Link-based like <code>NavTabs</code> (<code>items: { label, href, active, icon? }[]</code>), not controlled-state like <code>Tabs</code> — Console and Account are real routes (hard/soft navigation), not client-side panel switches.</li><li>Vertical stack layout, own column width, left-edge active indicator in place of <code>NavTabs</code>&#39;s bottom-underline.</li><li><code>icon</code> is an optional per-item slot (not required) — additive capacity matching the reference screenshot&#39;s aesthetic, but Console/Account don&#39;t need to adopt icons in this same change.</li><li>Follows existing <code>packages/ui</code> conventions: CSS Modules, semantic tokens only, no framework-specific link element baked in (consumes <code>&lt;Link&gt;</code> the same way <code>NavTabs</code>/<code>Breadcrumb</code> do per Next.js convention).</li><li>Storybook: new story under <code>packages/ui/src/stories/</code>, gallery entry in <code>DesignSystemOverview.stories.tsx</code>&#39;s Component Gallery section, verified with <code>pnpm --filter @sovereignfs/ui typecheck</code> per the Storybook hygiene rule in <code>CLAUDE.md</code>.</li><li>Explicitly <strong>out of scope for this RFC</strong>: grouped/sectioned rail items (category headers like Claude&#39;s &quot;General&quot;/&quot;Visuals&quot;/&quot;Desktop app&quot;). Console and Account&#39;s section lists are flat today; forcing a grouping API before either plugin has grouped data would be speculative. See Open questions.</li></ul><h3 id="b-redefine-dialogsize-md" tabindex="-1">B. Redefine <code>DialogSize.md</code> <a class="header-anchor" href="#b-redefine-dialogsize-md" aria-label="Permalink to &quot;B. Redefine \`DialogSize.md\`&quot;">​</a></h3><p>Change <code>Dialog.module.css</code>&#39;s <code>.md</code> from <code>36rem × 42rem</code> (portrait) to a landscape box sized for a rail-plus-content layout — starting point proposal, to refine visually during implementation: <strong><code>60rem × 40rem</code></strong> (960×640px). Desktop-only change (mobile already ignores size, see above).</p><p>This is a visible change to a public design-system value, so per NFR-04 it ships as a <strong>minor</strong> version bump (<code>0.47.0 → 0.48.0</code>) with a migration note in <code>docs/upgrade.md</code>, even though no shipped plugin currently sets <code>overlaySize: &quot;md&quot;</code> — the discipline applies to the contract, not current uptake.</p><h3 id="c-migrate-console-and-account" tabindex="-1">C. Migrate Console and Account <a class="header-anchor" href="#c-migrate-console-and-account" aria-label="Permalink to &quot;C. Migrate Console and Account&quot;">​</a></h3><ul><li><code>plugins/console/manifest.json</code> and <code>plugins/account/manifest.json</code>: <code>shellConfig.overlaySize</code> <code>&quot;lg&quot; → &quot;md&quot;</code>.</li><li>Delete the hand-rolled <code>.nav</code>/<code>.navLink</code> (<code>console.module.css:20-51</code>) and <code>.tabs</code>/<code>.tab</code> (<code>account.module.css</code>) rules; replace both layouts&#39; nav strips with <code>NavRail</code>.</li><li><strong>Mobile: no behavior change in this pass.</strong> Both layouts keep calling <code>useOverlaySecondRow</code> with a horizontal nav strip exactly as today. A future full drill-down list (section links as a plain vertical list filling the mobile screen, closer to Claude Mobile&#39;s settings pattern) is explicitly deferred — see Alternatives.</li></ul><h2 id="ui-flows" tabindex="-1">UI flows <a class="header-anchor" href="#ui-flows" aria-label="Permalink to &quot;UI flows&quot;">​</a></h2><p><strong>Desktop, inside the <code>md</code> dialog (soft-navigated overlay):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ ┌──────────┐  ┌───────────────────────────────┐ │</span></span>
<span class="line"><span>│ │ Overview │  │                                │ │</span></span>
<span class="line"><span>│ │ Users    │  │        (section content)       │ │</span></span>
<span class="line"><span>│ │ Groups   │  │                                │ │</span></span>
<span class="line"><span>│ │ Plugins  │  │                                │ │</span></span>
<span class="line"><span>│ │ Settings │  │                                │ │</span></span>
<span class="line"><span>│ │ ...      │  │                                │ │</span></span>
<span class="line"><span>│ └──────────┘  └───────────────────────────────┘ │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────┘</span></span></code></pre></div><p><strong>Mobile (unchanged):</strong> full-screen sheet, <code>OverlayHeader</code> title row + horizontal scrollable section strip as the second row, content below.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><p><strong>Add an <code>orientation</code> prop to the existing <code>NavTabs</code> instead of a new component.</strong> Rejected — the two aren&#39;t just a CSS flip: active-indicator side, container sizing (rail has an intrinsic column width; <code>NavTabs</code> is full-bleed), and icon-slot support diverge enough that <code>packages/ui</code> already treats <code>Tabs</code> and <code>NavTabs</code> as separate components rather than one parameterized component. A third distinct component keeps that precedent rather than breaking it with a conditional internal branch.</p><p><strong>Redefine <code>md</code> vs. add a new size token.</strong> Considered adding a new size alongside <code>md</code> to avoid touching a published value at all. Rejected for this RFC: <code>md</code> is unused by any shipped plugin today, so redefining it costs nothing in practice while adding a new token would leave <code>md</code> permanently occupying a value nothing was ever built for. Flagged here rather than silently decided — see Open questions for the exact target dimensions.</p><p><strong>Ship the full mobile drill-down (Claude Mobile-style list) now.</strong> Rejected for this RFC&#39;s scope — it&#39;s new mobile UX, not a reuse of an existing mechanism, and would meaningfully grow this change&#39;s surface. Noted as explicit future work so it isn&#39;t lost. <strong>Picked up by <a href="./../epics/plugin-accounts.html">epic task 14.6</a></strong> — see Update 3 above.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li><strong>Desktop title placement.</strong> Today&#39;s <code>&lt;h1&gt;Console&lt;/h1&gt;</code> / <code>&lt;h1&gt;Account&lt;/h1&gt;</code> sits above the horizontal nav (<code>console.module.css</code> <code>.title</code>, <code>account.module.css</code> equivalent). Claude&#39;s reference modal has no equivalent page title — the rail starts near the top. Does the title move into a rail header, get dropped on desktop, or stay as its own row above the rail+content pane? Needs a decision before implementation, not specified by this RFC.</li><li><strong>Standalone hard-navigation route treatment.</strong> Visiting <code>/console</code> or <code>/account</code> directly (no <code>Dialog</code> ancestor, <code>useOverlaySecondRow</code> is a no-op) currently renders the same horizontal header at full width. Does this route also switch to the vertical rail on desktop for consistency, or keep its current horizontal header? Not decided here.</li><li><strong>Grouped rail sections.</strong> Deferred, per Proposed design §A — flagged as possible future <code>NavRail</code> API growth (e.g. an optional <code>groups</code> shape) once Console or Account&#39;s list actually needs grouping.</li><li><strong>Exact <code>md</code> pixel dimensions.</strong> <code>60rem × 40rem</code> is a starting proposal, not a committed value — refine visually once the rail component exists and Console&#39;s real content (widest case: the users table) is laid out inside it.</li><li><strong>Full mobile drill-down list.</strong> Explicitly future work (see Alternatives) — not scheduled by this RFC, but the intent is recorded so it isn&#39;t forgotten. <strong>Picked up by <a href="./../epics/plugin-accounts.html">epic task 14.6</a></strong> — see Update 3 above.</li></ul><h2 id="adoption-path" tabindex="-1">Adoption path <a class="header-anchor" href="#adoption-path" aria-label="Permalink to &quot;Adoption path&quot;">​</a></h2><p>Documentation-first; no <code>ROADMAP.md</code> scheduling commitment yet, matching the pattern of RFCs 0076–0078. Tentatively a single epic task (9.22, Design System epic) covering all three parts (<code>NavRail</code> component, <code>md</code> resize, Console/Account migration) as one branch/PR, since the migration is meaningless without the other two and the pieces are small enough not to need independent review gates.</p><p><strong>Semver:</strong></p><ul><li><code>@sovereignfs/ui</code>: <strong>minor</strong> bump (<code>0.47.0 → 0.48.0</code>) under <code>feat/</code>, with a migration note in <code>docs/upgrade.md</code> for the <code>md</code> size change per NFR-04.</li><li><code>plugins/console</code> and <code>plugins/account</code>: version only their own <code>manifest.json</code> (never <code>package.json</code>, which stays pinned at <code>0.0.0</code>) — bump each manifest&#39;s <code>version</code> per the visual/behavioral change (currently <code>0.1.0</code> and <code>0.1.1</code> respectively).</li><li>Platform root <code>package.json</code>: minor bump at implementation time, per the standard &quot;each completed task bumps the minor version&quot; convention.</li></ul><h2 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Date</th><th>Change</th></tr></thead><tbody><tr><td>0.1</td><td>August 2026</td><td>Initial draft</td></tr></tbody></table>`,37)])])}const g=o(s,[["render",i]]);export{h as __pageData,g as default};
